def resource_entries():
    entries = [
        {"uri": "omniwrap://library/ir", "name": "Legacy library IR", "mimeType": "application/json"},
    ]
    if not SEMANTIC:
        return entries
    entries.extend((
        {"uri": "omniwrap://semantic/contract", "name": "Semantic API contract", "mimeType": "application/json"},
        {"uri": "omniwrap://semantic/diagnostics", "name": "Semantic diagnostics", "mimeType": "application/json"},
        {"uri": "omniwrap://agent/tasks", "name": "Versioned agent task corpus", "mimeType": "application/json"},
    ))
    entries.extend(
        {"uri": "omniwrap://semantic/operation/" + quote(str(item.get("operation_id", "")), safe=""), "name": "Operation " + str(item.get("operation_id", "")), "mimeType": "application/json"}
        for item in OPERATIONS
    )
    entries.extend(
        {"uri": "omniwrap://semantic/schema/" + quote(name, safe=""), "name": "Schema " + name, "mimeType": "application/json"}
        for name in SCHEMAS
    )
    entries.extend(
        {"uri": "omniwrap://semantic/auth/" + quote(name, safe=""), "name": "Authentication " + name, "mimeType": "application/json"}
        for name in AUTH_SCHEMES
    )
    entries.extend(
        {"uri": "omniwrap://agent/task/" + quote(str(item.get("task_id", "")), safe=""), "name": "Agent task " + str(item.get("task_id", "")), "mimeType": "application/json"}
        for item in AGENT_TASKS.get("tasks", [])
    )
    return entries


def read_resource(uri):
    if uri == "omniwrap://library/ir":
        value = LIBRARY
    elif uri == "omniwrap://semantic/contract" and SEMANTIC:
        value = SEMANTIC
    elif uri == "omniwrap://semantic/diagnostics" and SEMANTIC:
        value = {"items": DIAGNOSTICS}
    elif uri == "omniwrap://agent/tasks" and SEMANTIC:
        value = AGENT_TASKS
    elif uri.startswith("omniwrap://semantic/operation/") and SEMANTIC:
        value = find_operation(unquote(uri.rsplit("/", 1)[-1]))
        if value is None:
            raise KeyError(f"resource not found: {uri}")
    elif uri.startswith("omniwrap://semantic/schema/") and SEMANTIC:
        wanted = unquote(uri.rsplit("/", 1)[-1])
        key = wanted if wanted in SCHEMAS else None
        if key is None:
            raise KeyError(f"resource not found: {uri}")
        value = {"name": key, "schema": SCHEMAS[key]}
    elif uri.startswith("omniwrap://semantic/auth/") and SEMANTIC:
        wanted = unquote(uri.rsplit("/", 1)[-1])
        key = wanted if wanted in AUTH_SCHEMES else None
        if key is None:
            raise KeyError(f"resource not found: {uri}")
        value = {"name": key, "auth_scheme": AUTH_SCHEMES[key]}
    elif uri.startswith("omniwrap://agent/task/") and SEMANTIC:
        wanted = unquote(uri.rsplit("/", 1)[-1])
        value = next((item for item in AGENT_TASKS.get("tasks", []) if str(item.get("task_id", "")) == wanted), None)
        if value is None:
            raise KeyError(f"resource not found: {uri}")
    else:
        raise KeyError(f"resource not found: {uri}")
    return {"contents": [{"uri": uri, "mimeType": "application/json", "text": json.dumps(value, ensure_ascii=False, indent=2)}]}


